import re
from collections import defaultdict

def parse_ini(text: str) -> dict[str, dict[str, str]]:
    sections: dict[str, dict[str, str]] = defaultdict(dict)
    current_section = None
    pending_key = None
    pending_value_lines: list[str] = []
    default_section: dict[str, str] = {}

    def resolve_interpolation(value: str, section: str) -> str:
        def replace(match: re.Match[str]) -> str:
            key_expr = match.group(1)
            if ':' in key_expr:
                ref_section, ref_key = key_expr.split(':', 1)
                ref_section = ref_section.strip()
                ref_key = ref_key.strip().lower()
            else:
                ref_section = section
                ref_key = key_expr.strip().lower()

            if ref_section == 'DEFAULT':
                ref_dict = default_section
            elif ref_section in sections:
                ref_dict = sections[ref_section]
            else:
                raise KeyError(f"Section '{ref_section}' not found")

            if ref_key not in ref_dict:
                raise KeyError(f"Key '{ref_key}' not found in section '{ref_section}'")
            return resolve_interpolation(ref_dict[ref_key], ref_section)

        pattern = re.compile(r'\$\{([^}]*)\}')
        while True:
            new_value = pattern.sub(replace, value)
            if new_value == value:
                return new_value
            value = new_value
            if len(value) > 1000:  # Prevent infinite recursion
                raise ValueError("Circular interpolation detected")

    for line in text.splitlines():
        stripped = line.strip()
        if not stripped or stripped.startswith(';') or stripped.startswith('#'):
            continue

        if line.startswith(' ') or line.startswith('\t'):
            if pending_key is None:
                raise ValueError("Continuation line without preceding key")
            pending_value_lines.append(line.strip())
            continue

        section_match = re.match(r'^\s*\[([^\]]*)\]\s*$', line)
        if section_match:
            current_section = section_match.group(1).strip()
            if current_section == 'DEFAULT':
                current_section = None
            pending_key = None
            pending_value_lines = []
            continue

        if pending_key is not None:
            raise ValueError("Malformed line: expected continuation or section header")

        key_value_match = re.match(r'^\s*([^:=]+)([:=])(.*)', line)
        if not key_value_match:
            raise ValueError(f"Malformed line: {line!r}")

        key = key_value_match.group(1).strip().lower()
        separator = key_value_match.group(2)
        value_part = key_value_match.group(3).strip()

        inline_comment_match = re.match(r'^(.*?)\s*[;#](.*)', value_part)
        if inline_comment_match and not value_part.startswith('"'):
            value_part = inline_comment_match.group(1).strip()

        if value_part.startswith('"') and value_part.endswith('"'):
            value = value_part[1:-1]
        else:
            value = value_part

        pending_key = key
        pending_value_lines = [value]

    if pending_key is not None:
        raise ValueError("Malformed line: unterminated key-value pair")

    for section_name, section_dict in sections.items():
        for key, value in section_dict.items():
            sections[section_name][key] = resolve_interpolation(value, section_name)

    result: dict[str, dict[str, str]] = {}
    for section_name, section_dict in sections.items():
        if section_name is None:
            continue
        inherited = default_section.copy()
        inherited.update(section_dict)
        result[section_name] = inherited

    return result
