import re

def parse_duration(s: str) -> int:
    if not s.strip():
        raise ValueError("Empty or blank string")

    pattern = r'^(\s*\d+\s*[hms]\s*)+$'
    if not re.fullmatch(pattern, s, re.IGNORECASE):
        raise ValueError("Invalid format")

    parts = re.findall(r'(\d+)\s*([hms])', s, re.IGNORECASE)
    if not parts:
        raise ValueError("No valid parts found")

    seen_units = set()
    total_seconds = 0
    last_unit_order = -1
    unit_order = {'h': 0, 'm': 1, 's': 2}

    for num_str, unit in parts:
        unit_lower = unit.lower()
        current_order = unit_order[unit_lower]

        if current_order <= last_unit_order:
            raise ValueError("Units out of order or repeated")

        if unit_lower in seen_units:
            raise ValueError("Repeated unit")

        seen_units.add(unit_lower)
        last_unit_order = current_order

        num = int(num_str)
        if unit_lower == 'h':
            total_seconds += num * 3600
        elif unit_lower == 'm':
            total_seconds += num * 60
        elif unit_lower == 's':
            total_seconds += num

    return total_seconds
