import re
from collections import defaultdict

def top_customers(rows: list[dict], n: int) -> list[tuple[str, float]]:
    customer_totals = defaultdict(float)
    customer_names = {}

    for row in rows:
        customer = row.get("customer", "").strip()
        if not customer:
            continue

        amount_str = row.get("amount", "").strip()
        if not amount_str:
            continue

        try:
            amount = float(re.sub(r'[^\d.-]', '', amount_str))
        except ValueError:
            continue

        lower_customer = customer.lower()
        if lower_customer not in customer_names:
            customer_names[lower_customer] = customer

        customer_totals[lower_customer] += amount

    result = []
    for lower_customer, total in customer_totals.items():
        rounded_total = round(total, 2)
        if rounded_total == int(rounded_total):
            rounded_total = int(rounded_total)
        result.append((customer_names[lower_customer], float(rounded_total)))

    result.sort(key=lambda x: (-x[1], x[0]))
    return result[:n]
